mapper.insert:
INSERT INTO TB_CONCERT_INFO (
    ARTIST_NM_KOR
    , ARTIST_NM_FOR
    , CONCERT_YEAR
    , CONCERT_MONTH
    , CONCERT_DATE
    , CONCERT_TIME
    , VENUE
    , TCT_SITE
    , TCT_OPEN_AT
    , GENRE
    , POP_SCORE
    , ARTIST_IMAGE_URL
    , SEND_YN
    , REG_TIME
) VALUES (
    #{artistNmKor}
    , #{artistNmFor}
    , #{concertYear}
    , #{concertMonth}
    , #{concertDate}
    , #{concertTime}
    , #{venue}
    , #{tctSite}
    , #{tctOpenAt}
    , #{genre}
    , #{popScore}
    , #{artistImageUrl}
    , 'N'
    , NOW()
)
ON DUPLICATE KEY UPDATE
    ARTIST_NM_KOR = VALUES(ARTIST_NM_KOR)
    , ARTIST_NM_FOR = VALUES(ARTIST_NM_FOR)
    , CONCERT_YEAR = VALUES(CONCERT_YEAR)
    , CONCERT_MONTH = VALUES(CONCERT_MONTH)
    , CONCERT_DATE = VALUES(CONCERT_DATE)
    , CONCERT_TIME = VALUES(CONCERT_TIME)
    , VENUE = VALUES(VENUE)
    , TCT_SITE = VALUES(TCT_SITE)
    , TCT_OPEN_AT = VALUES(TCT_OPEN_AT)
    , GENRE = VALUES(GENRE)
    , ARTIST_IMAGE_URL = COALESCE(VALUES(ARTIST_IMAGE_URL), ARTIST_IMAGE_URL)

INSERT INTO TB_EMAIL_LOG (
    SUBJECT
    , EMAIL
    , REG_TIME
) VALUES (
    #{subject}
    , #{email}
    , NOW()
)

INSERT INTO TB_ARTIST_MSG (
    ARTIST_NM_KOR
    , CONCERT_YEAR
    , CONCERT_MONTH
    , CONCERT_DATE
    , SUBJECT
    , CONTENT
    , ARTIST_IMAGE_URL
    , REG_TIME
) VALUES (
    #{artistNmKor}
    , #{concertYear}
    , #{concertMonth}
    , #{concertDate}
    , #{subject}
    , #{content}
    , #{artistImageUrl}
    , NOW()
)

mapper.select:
/* AiMapper.selectConcertsMissingImage 이미지 없는 미래 공연 조회 */ SELECT A.CONCERT_NO AS concertNo , A.ARTIST_NM_KOR AS artistNmKor , A.ARTIST_NM_FOR AS artistNmFor , A.CONCERT_YEAR AS concertYear , A.CONCERT_MONTH AS concertMonth , A.CONCERT_DATE AS concertDate , A.CONCERT_TIME AS concertTime , A.VENUE AS venue , A.TCT_SITE AS tctSite , A.TCT_OPEN_AT AS tctOpenAt , A.POP_SCORE AS popScore , A.REG_TIME AS regTime , A.SEND_YN AS sendYn , A.GENRE AS genre , A.ARTIST_IMAGE_URL AS artistImageUrl FROM TB_CONCERT_INFO AS A WHERE STR_TO_DATE(CONCAT(A.CONCERT_YEAR, '-', LPAD(A.CONCERT_MONTH, 2, '0'), '-', LPAD(A.CONCERT_DATE, 2, '0')), '%Y-%m-%d') >= CURDATE() AND (A.ARTIST_IMAGE_URL IS NULL OR TRIM(A.ARTIST_IMAGE_URL) = '') AND A.ARTIST_NM_FOR IS NOT NULL AND TRIM(A.ARTIST_NM_FOR) <> '' AND (A.CONCERT_DATE IS NULL OR A.CONCERT_DATE <> '0')
AND STR_TO_DATE(CONCAT(A.CONCERT_YEAR, '-', LPAD(A.CONCERT_MONTH, 2, '0'), '-', LPAD(A.CONCERT_DATE, 2, '0')), '%Y-%m-%d') >= STR_TO_DATE(#{frYmd}, '%Y-%m-%d')
AND STR_TO_DATE(CONCAT(A.CONCERT_YEAR, '-', LPAD(A.CONCERT_MONTH, 2, '0'), '-', LPAD(A.CONCERT_DATE, 2, '0')), '%Y-%m-%d') <= STR_TO_DATE(#{toYmd}, '%Y-%m-%d')
ORDER BY A.POP_SCORE DESC, A.CONCERT_YEAR, A.CONCERT_MONTH, A.CONCERT_DATE LIMIT #{limit}

mapper.update:
/* AiMapper.updateConcertArtistImage 공연 이미지 URL 업데이트 */
UPDATE TB_CONCERT_INFO
   SET ARTIST_IMAGE_URL = #{artistImageUrl}
 WHERE CONCERT_NO = #{concertNo}

UPDATE TB_CONCERT_INFO
   SET CONCERT_TIME = #{concertTime}
     , VENUE = #{venue}
     , TCT_SITE = #{tctSite}
     , TCT_OPEN_AT = #{tctOpenAt}
 WHERE CONCERT_NO = #{concertNo}

UPDATE TB_ARTIST_MSG
   SET SEND_YN = 'Y'
 WHERE ARTIST_NM_KOR = #{artistNmKor}
   AND CONCERT_YEAR = #{concertYear}
   AND CONCERT_MONTH = #{concertMonth}
   AND CONCERT_DATE = #{concertDate}
